        value={inputValue}
        onChange={handleInputChange}
        placeholder={props.placeholder}
      />
      <ul>
        {suggestions.map((suggestion, index) => (
          <li key={index} onClick={() => handleClick(suggestion)}>
            {suggestion}
          </li>
        ))}
      </ul>
      {selected && (
        <p>
          Selected: {selected}
        </p>
