function MoveTo(currX, currY, targetX, targetY, currDirection) {
  var dx = targetX - currX;
  var dy = targetY - currY;

  // calculate the direction of the target
  var targetDirection = MathSign(dx, dy);

  // calculate the distance to the target
  var distance = mAbs(dx) + mAbs(dy);

  // move like a robot
  while (distance > 0) {
    var stepSize = MathMin(1, distance); // max 1 step per call
    distance -= stepSize;

    // move horizontally
    if (mAbs(dx) > mAbs(dy)) {
      if (targetDirection === 'R' && dx > 0) {
        TurnLike('R', 1); // turn right
      } else if (targetDirection === 'L' && dx < 0) {
        TurnLike('L', 1); // turn left
      }
      MoveLike(1); // move forward
      currX += MathSign(dx, dy);
    }
    // move vertically
    else {
      if (targetDirection === 'U' && dy > 0) {
        TurnLike('R', 1); // turn up
      } else if (targetDirection === 'D' && dy < 0) {
        TurnLike('L', 1); // turn down
      }
      MoveLike(1); // move up or down
      currY += MathSign(dy, dx);
    }

    // adjust direction accordingly
    if (currX === targetX && currY === targetY) {
      break;
    }
  }
}
```
