```
class PasswordGenerator {
  constructor minLength = 8, maxLength = 12, allowedChars = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*()_-+={}[]|;:/?"', excludedChars = 'il1oO0' {
    this.minLength = minLength;
    this.maxLength = maxLength;
    this.allowedChars = allowedChars;
    this.excludedChars = excludedChars;
  }

  generatePassword() {
    const length = Math.floor(Math.random() * (this.maxLength - this.minLength + 1)) + this.minLength;
    let password = '';
    for (let i = 0; i < length; i++) {
      const char = this.allowedChars.charAt(Math.floor(Math.random() * this.allowedChars.length));
      if (this.excludedChars.includes(char)) {
        i--;
      } else {
        password += char;
      }
    }
    return password;
  }

  checkPassword(password, confirmPassword = '') {
    if (!password || !confirmPassword) {
      throw new Error('Both passwords must be provided');
    }
    if (password.length < this.minLength || password.length > this.maxLength) {
      throw new Error(`Password must be between ${this.minLength} and ${this.maxLength} characters`);
    }
    if (password !== confirmPassword) {
      throw new Error('Passwords do not match');
    }
    if (this.excludedChars.includes(password.charAt(0)) || this.excludedChars.includes(password.charAt(password.length - 1))) {
      throw new Error('Password cannot start or end with an excluded character');
    }
    return true;
  }
}
