using System;

namespace Calculator
{
    class Program
    {
        static void Main(string[] args)
        {
            Console.WriteLine("Калькулятор");
            Console.WriteLine("***********");

            while (true)
            {
                Console.Write("Введите выражение (например, 2+2): ");
                string expression = Console.ReadLine();

                try
                {
                    double result = EvaluateExpression(expression);
                    Console.WriteLine($"Результат: {result}");
                }
                catch (Exception ex)
                {
                    Console.WriteLine($"Ошибка: {ex.Message}");
                }
            }
        }

        static double EvaluateExpression(string expression)
        {
            // Разбивая выражение на операцию и столько добавлено то
            string[] parts = expression.Split(' ');

            double operand1 = double.Parse(parts[0]);
            string operation = parts[1];
            double operand2 = double.Parse(parts[2]);

            double result = 0;

            switch (operation)
            {
                case "+":
                    result = operand1 + operand2;
                    break;
                case "-":
                    result = operand1 - operand2;
                    break;
                case "*":
                    result = operand1 * operand2;
                    break;
                case "/":
                    if (operand2 != 0)
                    {
                        result = operand1 / operand2;
                    }
                    else
                    {
                        throw new DivideByZeroException();
                    }
                    break;
                default:
                    throw new ArgumentException("Калькулятор не поддерживает такую операцию");
            }

            return result;
        }
    }
}
