```cpp
#include <Windows.h>
#include <iostream>
#include <ctime>
#include <cmath>
#include <atomic>

#define INTEGRAL_FORMULA 1 // 1 - cube, 2 - sin(x), 3 - x^2
#define METHOD 1 // 1 - rectangles, 2 - trapezoids, 3 - parabolic

atomic<bool> integralCalculated(false);
atomic<double> integralValue(0.0);
CRITICAL_SECTION mutex;

double f(double x) {
    if (INTEGRAL_FORMULA == 1) {
        return x * x * x;
    } else if (INTEGRAL_FORMULA == 2) {
        return sin(x);
    } else if (INTEGRAL_FORMULA == 3) {
        return pow(x, 2);
    }
    return 0.0;
}

void calculateIntegral(int method) {
    double a = 0.0, b = 1.0, h, sum = 0.0, sum1 = 0.0;
    int n = 100000; // число точек

    h = (b - a) / n;

    for (int i = 0; i < n; i++) {
        sum += f(a + i * h);
    }

    if (method == 1) { // прямоугольники
        integralValue = h * sum;
    } else if (method == 2) { // трапеции
        double sum1 = 0.0;
        for (int i = 0; i < n; i++) {
            if (i == 0 || i == n - 1) {
                sum1 += f(a + i * h);
            } else {
                sum1 += 2 * f(a + i * h);
            }
        }
        integralValue = (h / 2) * sum1;
    } else if (method == 3) { // параболы
        sum1 = 0.0;
        for (int i = 0; i < n; i++) {
            if (i == 0) {
                sum1 += f(a);
            } else if (i == n - 1) {
                sum1 += f(b);
            } else {
                sum1 += 2 * f(a + i * h);
            }
            if (i > 0 && i < n - 1) {
                sum1 += 4 * f(a + (i - 1) * h);
            }
        }
        integralValue = (h / 3) * sum1;
    }

    EnterCriticalSection(&mutex);
    integralCalculated = true;
    LeaveCriticalSection(&mutex);
}

int main() {
    HANDLE hThread;
    HANDLE hEvent; 

    CreateSemaphore(NULL, 0, n, "Semaphore");
    CreateMutex(NULL, FALSE, "Mutex");
    InitializeCriticalSection(&mutex);

    DWORD WINAPI threadProc(void* lParam) {
        calculateIntegral(METHOD);
        return 0;
    }

    for (int i = 0; i < 8; ++i) {
        hThread = CreateThread(NULL, 0, threadProc, NULL, 0, NULL);
    }

    WaitForMultipleObjects(8, hThread, TRUE, INFINITE);

    while (!integralCalculated) {
        Sleep(100);
    }

    LeaveCriticalSection(&mutex);
    printf("Calculated integral: %f\n", integralValue);

    DeleteCriticalSection(&mutex);
    CloseHandle(hThread);
    CloseHandle(hEvent);

    return 0;
}
```

В программе мы создаем n потоков с помощью функции `CreateThread` и передаем в каждый поток параметром функцию `calculateIntegral`, которая вычисляет приближенное значение интеграла методом прямоугольников, трапеций или парабол.

В главном потоке мы ожидаем завершения выполнения всех потоков с помощью функции `WaitForMultipleObjects`.

Мьютекс `mutex` используются для синхронизации доступа к переменной `integralCalculated` и `integralValue`, чтобы предотвратить доступ к ним из различных потоков до тех пор, пока не будет выполнено вычисление интеграла.<|start_header_id|>assistant<|end_header_id|>

