                <GoogleLogin
                  clientId={YOUR_GOOGLE_CLIENT_ID}
                  buttonText="Login with Google"
                  onSuccess={this.handleLoginResponse}
                  onFailure={this.handleLoginResponse}
                />
              </Grid>
            )}
          </Grid>
        </Container>
      </MuiThemeProvider>
    );
  }
}

// Render the app
ReactDOM.render(<SessionManager />, document.getElementById('root'));
