```javascript
class TicTacToe {
  constructor() {
    this.board = ['', '', '', '', '', '', '', '', ''];
    this.currentPlayer = 'X';
  }

  printBoard() {
    console.log(` ${this.board[0]} | ${this.board[1]} | ${this.board[2]} `);
    console.log('-----------');
    console.log(` ${this.board[3]} | ${this.board[4]} | ${this.board[5]} `);
    console.log('-----------');
    console.log(` ${this.board[6]} | ${this.board[7]} | ${this.board[8]} `);
  }

  isValidMove(position) {
    return this.board[position] === '';
  }

  makeMove(position) {
    if (this.isValidMove(position)) {
      this.board[position] = this.currentPlayer;
      this.currentPlayer = this.currentPlayer === 'X' ? 'O' : 'X';
    }
  }

  checkWin() {
    const winningPositions = [[0, 1, 2], [3, 4, 5], [6, 7, 8], [0, 3, 6], [1, 4, 7], [2, 5, 8], [0, 4, 8], [2, 4, 6]];
    for (let i = 0; i < winningPositions.length; i++) {
      const position1 = winningPositions[i][0];
      const position2 = winningPositions[i][1];
      const position3 = winningPositions[i][2];
      if (this.board[position1] === this.board[position2] && this.board[position2] === this.board[position3] && this.board[position1] !== '') {
        return this.board[position1];
      }
    }
    return null;
  }

  minimax(position, player) {
    if (this.checkWin() !== null) {
      return this.checkWin() === player ? 1 : -1;
    }
    if (player === 'X') {
      let bestScore = -Infinity;
      for (let i = 0; i < this.board.length; i++) {
        if (this.isValidMove(i)) {
          this.makeMove(i);
          bestScore = Math.max(bestScore, this.minimax(position, 'O'));
          this.makeMove('');
        }
      }
      return bestScore;
    } else {
      let bestScore = Infinity;
      for (let i = 0; i < this.board.length; i++) {
        if (this.isValidMove(i)) {
          this.makeMove(i);
          bestScore = Math.min(bestScore, this.minimax(position, 'X'));
          this.makeMove('');
        }
      }
      return bestScore;
    }
  }

  makeComputerMove() {
    let bestScore = -Infinity;
    let bestMove = 0;
    for (let i = 0; i < this.board.length; i++) {
      if (this.isValidMove(i)) {
        this.makeMove(i);
        const score = this.minimax(i, 'O');
        this.makeMove('');
        if (score > bestScore) {
          bestScore = score;
          bestMove = i;
        }
      }
    }
    this.makeMove(bestMove);
  }

  play() {
    while (true) {
      this.printBoard();
      const position = prompt('Enter your move (1-9)');
      if (this.isValidMove(parseInt(position) - 1)) {
        this.makeMove(parseInt(position) - 1);
      } else {
        alert('Invalid move. Try again!');
        continue;
      }
      const winner = this.checkWin();
      if (winner !== null) {
        this.printBoard();
        if (winner === 'X') {
          console.log('You win!');
        } else {
          console.log('Computer wins!');
        }
        break;
      }
      this.makeComputerMove();
      const winner = this.checkWin();
      if (winner !== null) {
        this.printBoard();
        if (winner === 'X') {
          console.log('Computer wins!');
        } else {
          console.log('You win!');
        }
        break;
      }
    }
  }
}

