To rotate a PDF in Delphi 7, you'll need to use a library that can manipulate PDF files. One popular option is the iText library, which is a popular open-source library for creating and manipulating PDF files.

Here's an example of how you can use iText to rotate a PDF in Delphi 7:
```delphi
unit RotatePDF;

interface

uses
  System.SysUtils,
  System.Types,
  iTextSharp.text,
  iTextSharp.text.pdf;

type
  TPDFRotator = class
  public
    procedure RotatePDFFile(const PDFFile: string; Rotation: PDFRotation);
  end;

implementation

const
  PDFRotation = (rot0, rot90, rot180, rot270);

var
  pdf: TPDFDocument;

procedure TPDFRotator.RotatePDFFile(const PDFFile: string; Rotation: PDFRotation);
var
  pdfReader: TPDFReader;
  pdfWriter: TPDFWriter;
begin
  // Create a PDF reader
  pdfReader := TPDFReader.Create(nil);
  try
    // Open the PDF file
    pdfReader.LoadFromFile(PDFFile);
    // Create a new PDF document
    pdf := TPDFDocument.Create(nil);
    try
      // Set the rotation
      pdf.SetRotation(Rotation);
      // Copy the pages from the original PDF
      for var i := 0 to pdfReader.GetNumberOfPages - 1 do
      begin
        pdf.AddPage(pdfReader.GetPage(i));
      end;
      // Save the rotated PDF
      pdfWriter := TPDFWriter.Create(pdf);
      try
        pdfWriter.SaveToFile(PDFFile + '.rotated.pdf');
      finally
        pdfWriter.Free;
      end;
    finally
      pdf.Free;
    end;
  finally
    pdfReader.Free;
  end;
end;

initialization
  PDFRotator := TPDFRotator.Create;

end.
```
To use this code, simply create an instance of the `TPDFRotator` class and call the `RotatePDFFile` method, passing in the path to the PDF file you want to rotate and the rotation angle (e.g. `rot90` for a 90-degree rotation).

